def compute(vars):
    cib_markets_net_interest_income = vars["v1"]
    managed_net_interest_income = vars["v2"]

    if managed_net_interest_income == 0:
        return None

    percentage = cib_markets_net_interest_income / (managed_net_interest_income / 100)

    return {
        "value": percentage,
        "trace": {
            "cib_markets_net_interest_income": cib_markets_net_interest_income,
            "managed_net_interest_income": managed_net_interest_income,
            "value": percentage,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
